            <Menu
                anchorEl={submenuAnchor}
                anchorOrigin={{ horizontal: 'right', vertical: 'top' }}
                onClose={handleCloseSubmenu}
                open={submenu === 'speedMode'}
                slotProps={{ list: { 'aria-label': 'Speed choices', onKeyDown: handleNestedMenuKeyDown } }}
                transformOrigin={{ horizontal: 'left', vertical: 'top' }}
            >
                {SPEED_MODE_OPTIONS.map(({ label, value }) => (
                    <MenuItem data-speed-mode={value} key={value} onClick={handleSpeedModeChange}
                        selected={value === (settings.speedMode ?? 'default')}>
                        <ListItemText primary={label} secondary={value === 'fast' ? 'Higher provider usage' : undefined} />
                    </MenuItem>
                ))}
            </Menu>
            <Menu
                anchorEl={securityMenuAnchor}
                id="action-agent-security-menu"
                onClose={handleCloseSecurityMenu}
                open={!!securityMenuAnchor}
                slotProps={{ list: { 'aria-label': 'Security settings' } }}
            >
                {PERMISSION_MODE_OPTIONS.map(({ description, label, value }) => (
                    <MenuItem
                        data-permission-mode={value}
                        key={value}
                        onClick={handlePermissionModeChange}
                        selected={value === settings.permissionMode}
                    >
                        <ListItemText primary={label} secondary={description} />
                    </MenuItem>
                ))}
            </Menu>
        </Box>
    )
